// Build timelines from compact [t0,t1,...,t8] arrays (null = tick missing)
function makeTimelines(agentsData, tickDateFn) {
  return agentsData.map(({ id, name, ticks }, idx) => ({
    agentId: id,
    agentName: name,
    color: PALETTE[idx % PALETTE.length],
    trajectory: ticks
      .map((m, i) => m !== null ? { t: tickDateFn(i), value: +(m / 100).toFixed(3), label: `Tick ${i}` } : null)
      .filter(Boolean)
  }));
}

